'use strict'
// Extend the review guard only to restore targets generated by this test process.
const base=require('./codex-review-round5-harness.cjs'),assert=require('node:assert/strict'),sql=require('../node_modules/mssql'),migrate=require('../scripts/db-migrate.cjs')
const targets=new Set(),safe=base.safeDatabase,name=migrate.rehearsalName,restore=migrate.restoreCopy
migrate.rehearsalName=()=>{const target=name();assert.match(target,migrate.REHEARSAL_DATABASE);targets.add(target);return target}
base.safeDatabase=database=>{if(!targets.has(database))safe(database)}
migrate.restoreCopy=async(...args)=>{assert.ok(targets.has(args[2]));const r=await restore(...args);console.log('CRP1_DATABASE '+JSON.stringify({operation:'CREATE',database:args[2]}));return r}
for(const method of ['query','batch']){
 const original=sql.Request.prototype[method]
 sql.Request.prototype[method]=function(statement,...args){
  if(typeof statement==='string')for(const match of statement.matchAll(/\b(BACKUP\s+(?:DATABASE|LOG)|RESTORE\s+DATABASE)\s+\[?([a-z0-9_]+)\]?/gi)){
   if(/^RESTORE/i.test(match[1]))assert.ok(targets.has(match[2]));else safe(match[2])
  }
  return original.call(this,statement,...args)
 }
}
console.log('CRP1_OPS backup source is disposable; restore target must be generated by this process')
